const nodes=[
{id:'scope',stage:0,type:'all',title:'研究框架与对象拆分',short:'先划清湖泊水体、其他湿地与水生态',page:'1—8',pdf:10,question:'这份报告究竟研究哪些对象，最后要回答什么管理问题？',inputs:['研究区：青海湖及其流域（报告记载流域面积29661 km²）','对象A：湖泊水体的面积、水位、水量、水温、透明度、盐度与水生态','对象B：遥感分类中的“除水体外湿地”','未来对象：气候情景下湖泊扩张及道路、居民点、生境风险'],tools:['多源遥感与水文资料','统计关系与半物理模型','随机森林分类/回归','GIS空间叠加','文献与监测资料综合'],model:'没有一个覆盖全报告的总模型；报告由多条相互关联、但计算上相对独立的分析线组成。',process:['先重建历史变化','再分析气象联系与水生态响应','预测未来水量并换算水位、面积','叠加基础设施并提出应对措施'],outputs:['历史变化序列','环境与生态响应认识','未来水量/水位/面积情景值','暴露对象与管理建议'],result:'主线是“历史变化 → 影响因素与生态响应 → 未来趋势 → 暴露风险 → 保护应对”。',handoff:[['lake','进入湖泊水文线，生成面积—水位—水量长序列'],['wetland','进入其他湿地线，生成8期湿地范围与面积'],['eco','生态线汇集水温、水质、生物与生境证据']],note:'网站中的连线是依据报告内容整理的逻辑路线，不是原报告提供的一张统一模型流程图。'},
{id:'lake',stage:1,type:'lake',title:'湖泊面积、水位与水量重建',short:'NDWI + 历史关系式 → 1956—2024序列',page:'9—14',pdf:18,image:23,question:'如何把不同来源的湖面、水位资料变成历史分析和未来换算所需的统一序列？',inputs:['1956—2020年面积、水位：国家青藏高原科学数据中心','2021—2023年面积、水位：青海省水资源公报','2024-10-23 Landsat影像','历史各年的面积S与水位H'],tools:['Landsat遥感影像','绿波段与近红外波段','人工边界修正','面积—水位回归与相邻年份水量公式'],model:'2024水面用NDWI=(Green−NIR)/(Green+NIR)提取，阈值后人工修正；2024水位由1956—2023面积—水位线性关系估算。相邻年份水量增量由面积和水位的几何公式计算，再累积为相对水量变化。',process:['辐射校正并计算NDWI','提取2024湖泊边界，删除山影和河流误分','用历史面积—水位关系估算2024水位','用相邻两年面积、水位计算ΔV','建立水位—面积、水位—累计水量变化两套关系'],outputs:['逐年湖泊面积S','逐年湖泊水位H','逐年水量变化ΔV及相对基准年的累计变化','可用于未来换算的面积—水位、水量—水位关系'],result:'2004年为转折点。1990—2004年面积减少127.74 km²、水位下降1.42 m、水量减少6.04 km³；2004—2024年分别增加364.36 km²、4.11 m和18.03 km³。2024年面积4569.83 km²、水位3196.97 m。',handoff:[['driver','逐年ΔV作为因变量，与降水、气温和蒸发比较'],['predict','1956—2024年ΔV作为随机森林训练目标'],['convert','历史水位—面积、水位—水量关系把未来水量转成水位和面积']],note:'2024年水位是关系式估算值；多源资料不等于完全同口径的连续站点观测。',figure:'图3：1990、2004与2024年湖泊边界（正文14页）'},
{id:'wetland',stage:1,type:'wetland',title:'除水体外湿地分类',short:'Landsat + RF分类 → 8期湿地分布',page:'51—53',pdf:60,image:61,question:'湖面扩大时，流域内其他湿地的面积和格局怎样变化？',inputs:['1990、1995、2000、2005、2010、2015、2020、2024年Landsat','云量<10%，优选6—9月；缺景时采用邻近年份','Google Earth高分辨率影像与已发表湿地数据集','3352个手动识别的湿地/非湿地样本'],tools:['Google Earth Engine中值合成','样本迁移','光谱、地形、水体/植被指数、植被覆盖度、物候特征','随机森林分类与分类后去噪'],model:'以多类遥感和环境特征为输入、湿地/非湿地样本为标签，逐期训练或迁移随机森林分类器，输出“除水体外”的湿地像元。',process:['筛选并合成各期Landsat','构建样本并迁移到其他年份','计算输入特征','随机森林分类','去除斑点噪声并统计面积、斑块变化'],outputs:['8期湿地二值/分类分布图','各期湿地总面积','单个湿地斑块面积及破碎化空间线索'],result:'1990年2804.92 km²，1995年2088.97 km²，2010年回升至2483.36 km²，2024年2081 km²；西北部减少和破碎化最明显。',handoff:[['carbon','湿地面积乘以单位面积碳平衡参数，估算湿地总碳汇及面积变化影响'],['action','湿地分布、减少区和监测缺口用于提出保护与监测措施']],note:'本章未列出各期混淆矩阵、总体精度或Kappa；分类结果不能当作无误差真值，也不能把所有减少都归因于湖泊扩张。',figure:'图21：1990年以来湿地总面积变化（正文52页）'},
{id:'driver',stage:2,type:'lake',title:'水量变化的气候因素分析',short:'ΔV 对比 P / T / PET',page:'15—17',pdf:24,question:'历史湖泊水量变化与降水、气温和蒸发的关系如何？',inputs:['上一环节生成的逐年湖泊水量变化ΔV','中国1 km逐月降水P、平均气温T、潜在蒸散发PET数据（1901—2024）','青海湖流域范围与湖面范围'],tools:['流域统计','年尺度聚合','时间趋势和阶段对比','气象因子与年水量变化的统计关系'],model:'这是统计关联分析，不是完整水量平衡模型。报告比较P、T、流域PET、湖面PET与ΔV的同步关系和阶段变化。',process:['逐月数据汇总为逐年指标','提取流域或湖面平均值','计算长期趋势与阶段均值','把每年气象量与ΔV比较'],outputs:['1990—2024年P/T/PET时间序列','各因子与ΔV的统计关系','“降水主导、蒸发次要影响”的解释'],result:'报告给出降水与湖泊年水量变化关系最强（文中标R²=0.60），并判断降水变化为主要驱动，蒸发也有影响。',handoff:[['predict','选择P、T、PET作为未来水量随机森林的三个输入特征'],['eco','暖湿化背景为水温、盐度、营养盐及生物响应提供解释背景']],note:'相关性不是严格的因果贡献分解；第16页部分负值仍写作R²，统计量标注口径需要核实。'},
{id:'temp',stage:2,type:'lake',title:'表层水温重建',short:'air2water + MOD11A1 → 逐日水温',page:'17—22',pdf:26,question:'没有1990年以来连续湖温实测时，如何重建逐日湖面温度？',inputs:['刚察气象站逐日气温，经0.65 ℃/100 m直减率校正到近水面','MOD11A1日间与夜间1 km湖面温度','湖泊矢量向内侵蚀1 km后的纯水体区域'],tools:['GEE批量处理MOD11A1','改进air2water半物理模型','粒子群优化PSO','Nash–Sutcliffe效率系数作为率定目标'],model:'air2water把湖泊能量平衡简化为气温驱动的水温方程；改进版增加冰面、水面和冰水混合状态，共含15个需率定参数。2000—2012率定，2013—2017验证。',process:['求MODIS昼夜均温并剔除岸边混合像元','用PSO搜索模型参数','率定后以气温驱动1990—2022逐日模拟','统计年均值、非结冰期均值及空间差异'],outputs:['1990—2022逐日连续湖面温度序列','年均水温趋势','非结冰期空间分布和变化率'],result:'年均湖面水温约2.5—4 ℃，1990—2022年显著升高，报告给出的速率为0.019 ℃/年；湖泊东部升温较快。',handoff:[['eco','水温序列用于解释浮游生物、鱼类、冰封期和湖水混合过程变化'],['carbon','水温升高—结冰期缩短—混合期变化用于讨论湖泊碳循环机制']],note:'这是模型重建序列；逐日连续不等于每天都有直接卫星或现场测量。'},
{id:'water',stage:2,type:'lake',title:'透明度与盐度遥感反演',short:'MODIS参考 + Landsat长序列 → SD → 盐度',page:'23—38',pdf:32,question:'怎样利用遥感获得1990—2024年的透明度和盐度？',inputs:['MODIS MODOCGA水色反射率与质量波段','2000—2019年青藏高原>50 km²湖泊同步Landsat TM/MODIS样本','青藏高原湖泊实测盐度','青海湖1990—2024年Landsat'],tools:['Lee等透明度半分析模型','Landsat绿波段多项式回归','盐度—年最大透明度多项式回归','Pettitt突变检验、趋势与滞后相关'],model:'先用MODIS半分析模型得到透明度参考值，再以2250个同步样本建立Landsat绿波段—透明度模型（文中R²=0.72）；随后以实测盐度和透明度最大值建立盐度模型（R²=0.51），形成两级反演链。',process:['质量筛选同步影像','用MODIS计算透明度参考值','拟合并应用Landsat透明度模型','以透明度反演盐度','计算长期趋势、突变年、空间差异和滞后相关'],outputs:['1990—2024透明度栅格/年度统计','1990—2024盐度栅格/年度统计','突变年份与面积—盐度滞后关系'],result:'透明度总体显著上升，盐度总体显著下降；报告识别2003年为二者阶段变化的突变点，并认为变化与降水、径流和湖泊扩张相适应。',handoff:[['eco','透明度、盐度作为水生态背景，解释浮游动物、鱼类和藻类适生条件'],['carbon','盐度和混合状态用于讨论湖泊生产力与碳汇变化']],note:'盐度依赖透明度的二次推算，误差会沿模型链传递；二者并非两套相互独立的观测。'},
{id:'eco',stage:3,type:'lake',title:'水生态与生境响应综合',short:'遥感 + 调查 + 文献 → 生态机制链',page:'38—50、67—69',pdf:47,question:'湖面扩大、水温升高、盐度下降，对不同生物和生境意味着什么？',inputs:['前序环节的湖面、水温、透明度和盐度变化','TN、TP、Chl-a、浮游植物/动物调查与文献','裸鲤资源、水鸟监测及既有研究','新淹没湖滨带与主湖区资料'],tools:['Landsat 8 Chl-a经验反演（56组实测样本）','趋势与空间格局分析','已有监测资料和文献的机制综合'],model:'本环节不是单一生态模型。定量遥感反演与文献/调查综合并行，构建“水文变化—理化环境—生产者—消费者—生境”的解释链。',process:['分析TN/TP及Chl-a时空变化','整理浮游植物、浮游动物、鱼类和水鸟响应','联系新淹没区营养释放、浅水光照与刚毛藻增长','辨析水域增加和岸带生境损失的双向效应'],outputs:['Chl-a与浮游植物变化认识','鱼类和水鸟的潜在响应路径','湖泊扩张的生态收益与生态风险清单'],result:'报告认为2004年后浮游植物丰度与Chl-a回升，蓝藻比重增加；水域扩大增加部分可用水面，但淹没湖岸湿地和筑巢地，也可能促进局地营养化和刚毛藻增长。',handoff:[['action','生态风险与观测缺口转化为水生态监测、遥感反演、污染控制和生境保护建议']],note:'鱼类、鸟类等部分结论主要来自文献和监测综合，不能都解释为本项目完成的定量因果实验。'},
{id:'carbon',stage:3,type:'wetland',title:'湖泊—湿地碳源汇估算',short:'面积 × 单位面积参数 → 总碳汇',page:'53—55',pdf:62,question:'湖泊和其他湿地面积变化怎样换算为碳汇影响？',inputs:['2024湖泊面积4569.83 km²','2024其他湿地面积2081 km²','单位面积湖泊碳汇−197.1 gC/m²/年','单位面积湿地碳平衡−239.6 gC/m²/年','流域陆地植被净生态系统碳交换参数'],tools:['面积乘单位面积碳平衡的尺度扩展','与流域陆地生态系统总碳吸收量比较','湖泊混合期、营养盐和初级生产力的机制讨论'],model:'总碳汇≈面积×单位面积年碳平衡。面积变化造成的碳汇变化也按同一单位参数换算；过程机制部分不进入一个动态碳循环模型。',process:['统一面积单位','分别估算湖泊、湿地总碳汇','估算面积增减带来的变化量','与流域陆地碳吸收比较并讨论未来机制'],outputs:['湖泊总碳汇估算','其他湿地总碳汇估算','面积变化对碳汇的量级影响','需要涡动通量和湖泊过程观测的研究缺口'],result:'报告估算2024年湖泊碳汇约90万吨/年，其他湿地约49.86万吨/年；认为面积变化对全流域碳汇影响有限，但湖泊/湿地本身的绝对碳汇不可忽视。',handoff:[['action','碳通量观测不足转化为不同湿地类型布设涡动塔和加强过程监测的建议']],note:'第52页面积差为723.92 km²，第54页估算却采用715.98 km²，数值口径不一致；固定单位参数不能替代动态碳模型。'},
{id:'predict',stage:4,type:'future',title:'未来年水量变化预测',short:'P/T/PET + RF + GAN → 年ΔV',page:'57—58',pdf:66,image:67,question:'历史数据怎样训练模型，并接收未来气候情景？',inputs:['1956—2024年逐年水量变化ΔV（来自湖泊历史重建）','同期年降水P、年均温T、年潜在蒸发PET','SSP1-1.9、SSP2-4.5、SSP5-8.5未来P/T/PET'],tools:['随机森林回归RF','训练/验证/测试按6∶2∶2划分','生成对抗网络GAN数据增强','5折交叉验证'],model:'RF学习f(P,T,PET)→年水量变化ΔV。GAN用于扩充小样本训练数据；训练好的RF接收未来三种SSP下的逐年气象值，逐年输出ΔV。',process:['构造约69年的年尺度样本','划分训练、验证、测试集','GAN生成扩充样本','5折交叉验证调参与训练RF','输入未来气候序列得到2025—2100逐年ΔV'],outputs:['训练集R²=0.905、RMSE=0.318 km³；测试集R²=0.691、RMSE=0.544 km³','三种SSP下逐年预测水量变化ΔV','从2024年起累积的水量增量'],result:'三个情景在2070年前的累计变化接近，2100年高排放情景增幅更大；模型真正预测的是“年水量变化”，不是湿地类型和湖岸线。',handoff:[['convert','把逐年ΔV累积为相对2024年的水量增量，再通过历史关系式换算水位与面积']],note:'报告未充分说明随机划分是否保持时间独立、GAN样本如何与测试集隔离、使用哪些CMIP6模式及如何订正；测试指标不能验证2100年外推。',figure:'图23：随机森林水量变化预测模型（正文58页）'},
{id:'convert',stage:4,type:'future',title:'水量 → 水位 → 面积换算',short:'累计ΔV + 历史几何关系 → 未来湖面',page:'59—61',pdf:68,image:69,question:'随机森林只输出水量变化，怎样得到未来水位、面积和边界？',inputs:['未来RF输出的逐年ΔV','从2024年起的累计水量变化','历史水位—累计水量关系','历史面积—水位线性关系','SRTM高程'],tools:['逐年累加','历史回归关系换算','SRTM等高程条件下的湖面边界绘制'],model:'累计水量增量先映射为水位H，再由H映射为湖泊面积S；代表年份结果汇总为表6。高程用于把预测水位转换成空间淹没范围。',process:['累积每年ΔV','换算2035/2050/2070/2100水位','再换算面积','依据预测水位与地形绘制未来边界'],outputs:['三情景四个代表年份的水量、水位、面积增量','可供GIS叠加的未来湖面边界'],result:'表6：2050年水位增加2.03—2.46 m、面积增加188.70—220.76 km²；2100年水位增加6.40—7.76 m、面积增加573.87—696.69 km²。',handoff:[['risk','未来水位/湖面边界与铁路、公路、房屋点叠加，识别暴露对象']],note:'历史关系外推到更高水位会累积RF与几何换算误差；报告没有给出未来边界的不确定性范围。',figure:'图24：三种气候情景下未来变化（正文60页）'},
{id:'risk',stage:5,type:'future',title:'道路与居民点暴露分析',short:'未来湖面 + 设施点线 → 暴露数量/长度',page:'62—67',pdf:71,image:75,question:'预测的湖面扩张怎样变成可用于管理的风险信息？',inputs:['上一环节的代表性未来湖面或水位（约1、2、4、6、8 m）','青藏铁路、西和高速、环湖公路矢量','房屋点位置','SRTM地形'],tools:['GIS空间叠加','点在淹没区内统计','道路与淹没区相交长度统计','重点区域目视判读'],model:'这是静态暴露分析：湖面范围∩设施位置。它统计“可能位于水面范围内”的对象，没有进一步模拟波浪、岸蚀、工程防护或人口脆弱性。',process:['构建不同水位的湖面范围','叠加铁路、高速和环湖道路','统计相交路段与房屋点','识别布哈河口等集中暴露区'],outputs:['受影响道路位置和长度','受影响房屋点数量及空间分布','重点风险区'],result:'约2 m时统计115个房屋点；约4 m时305个，并有约3 km铁路、约50 km公路面临淹没；约6 m时586个房屋点；约8 m时981个。',handoff:[['action','暴露位置和程度用于提出筑坝、抬高、改道、搬迁及更精细基础数据调查']],note:'房屋点不等于户数或人口；暴露不等于风险全貌，工程设计还需更高精度地形、水动力和实地调查。',figure:'图28：不同水位下居民点影响（正文66页）'},
{id:'action',stage:5,type:'future',title:'监测、保护与适应措施',short:'证据缺口 + 风险结果 → 行动方案',page:'70—76',pdf:79,question:'前面每条分析线，最终分别支持什么行动？',inputs:['气象—水量关系与未来扩张结果','水生态变化与机理不确定性','其他湿地分布、面积和碳汇结果','道路、居民点暴露位置','各章节暴露出的监测和验证缺口'],tools:['问题—证据—措施映射','管理与科研需求综合','工程、生态与制度措施分类'],model:'本环节是决策综合，不是数值模型。不同上游结果分别进入水量监测、水生态调查、湿地保护、工程适应和管理协调。',process:['把数据不足转化为监测补点','把生态机制不清转化为过程调查','把暴露对象转化为工程与搬迁需求','把跨区域问题转化为协同管理和生态补偿'],outputs:['水量平衡监测与水文气象模型提升建议','水生态过程观测与遥感反演建议','不同类型湿地、生态容量和碳通量监测建议','道路/居民点工程应对、生态补偿和管理机制建议'],result:'形成四类主建议：水量平衡与预测、水生态监测、湿地与生态容量监测、国家公园体制机制，并提出局地工程适应方向。',handoff:[['scope','形成“持续监测—模型更新—风险再评估—措施调整”的反馈闭环']],note:'这些是报告在2025年7月提出的研究和管理建议，不表示相应工程已立项或实施。'}
];
const stages=['00 研究起点','01 历史变化识别 ↓','02 环境因素与理化变化 ↓','03 生态功能与响应 ↓','04 未来情景预测 ↓','05 风险与管理应用'];
let selected='lake',filter='all',tab='transfer';
const $=s=>document.querySelector(s),node=id=>nodes.find(n=>n.id===id),list=a=>`<ul>${a.map(t=>`<li>${t}</li>`).join('')}</ul>`;
function renderMatrix(){$('#matrix').innerHTML=nodes.slice(1).map((n,i)=>`<article class="matrix-row" data-matrix="${n.id}" tabindex="0"><span class="matrix-no">${String(i+1).padStart(2,'0')}</span><div><small>环节</small><strong>${n.title}</strong></div><div><small>核心方法/模型</small><p>${n.model.split('。')[0]}。</p></div><div><small>直接产出</small><p>${n.outputs.slice(0,2).join('；')}</p></div><div><small>下一步怎么用</small><p>${n.handoff.map(h=>`${node(h[0]).title}：${h[1]}`).join('；')}</p></div><span class="matrix-open">展开 ↗</span></article>`).join('');document.querySelectorAll('[data-matrix]').forEach(el=>{const go=()=>{filter='all';updateFilters();select(el.dataset.matrix,true)};el.onclick=go;el.onkeydown=e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();go()}}});}
function renderMap(){const q=$('#search').value.trim().toLowerCase();let count=0;$('#nodes').innerHTML=stages.map((s,i)=>{const arr=nodes.filter(n=>n.stage===i&&(filter==='all'||n.type===filter||n.id==='scope')&&JSON.stringify(n).toLowerCase().includes(q));count+=arr.length;return arr.length?`<div class="stage"><div class="stage-title">${s}</div><div class="node-grid">${arr.map(n=>`<button class="node ${n.type} ${n.id===selected?'selected':''}" data-node="${n.id}" aria-pressed="${n.id===selected}"><small>${n.type==='wetland'?'其他湿地':n.type==='future'?'预测与应对':n.type==='lake'?'湖泊水体':'研究框架'}</small><strong>${n.title}</strong><small>${n.short}</small><span class="arrow">↗</span></button>`).join('')}</div></div>`:''}).join('');$('#empty').hidden=!!count;document.querySelectorAll('[data-node]').forEach(b=>b.onclick=()=>select(b.dataset.node));}
function select(id,scroll=false){selected=id;tab='transfer';renderMap();renderDetail();if(scroll||innerWidth<680)$('#detail').scrollIntoView({behavior:'smooth',block:'start'});}
function transferDiagram(n){return `<div class="transfer-strip"><div><small>输入</small><b>${n.inputs.length}类数据</b></div><i>→</i><div><small>方法/模型</small><b>${n.tools.slice(0,2).join(' + ')}</b></div><i>→</i><div><small>本步输出</small><b>${n.outputs.length}项结果</b></div></div><div class="field"><h4>本步交给下一步什么</h4><div class="handoffs">${n.handoff.map(h=>`<button data-jump="${h[0]}"><span>输出 → ${node(h[0]).title}</span><strong>${h[1]}</strong></button>`).join('')}</div></div>`;}
function renderDetail(){const n=node(selected);const body=tab==='transfer'?`${transferDiagram(n)}<div class="field result"><h4>本环节关键结果</h4><p>${n.result}</p></div>`:tab==='method'?`<div class="field"><h4>01 / 输入数据与变量</h4>${list(n.inputs)}</div><div class="field"><h4>02 / 工具、数据产品与算法</h4>${list(n.tools)}</div><div class="modelbox"><h4>03 / 模型到底做什么</h4><p>${n.model}</p></div><div class="field"><h4>04 / 实际处理顺序</h4><ol>${n.process.map(x=>`<li>${x}</li>`).join('')}</ol></div>`:tab==='output'?`<div class="field"><h4>直接输出</h4>${list(n.outputs)}</div><div class="field result"><h4>报告结果</h4><p>${n.result}</p></div>${transferDiagram(n)}<div class="caution">解释边界：${n.note}</div>`:`<div class="field"><h4>原报告定位</h4><p>正文 ${n.page} 页；起始位置对应PDF第 ${n.pdf} 页。</p></div>${n.image?`<img class="evidence" src="assets/page-${n.image}.webp" alt="${n.figure}"><div class="imagehint">${n.figure} · 点击图页放大</div>`:'<p class="imagehint">此环节以原报告方法文字或综合讨论为主，可通过下方链接查看完整原文。</p>'}<div class="caution">${n.note}</div>`;$('#detail').innerHTML=`<div class="detail-top"><span>节点 ${String(nodes.indexOf(n)+1).padStart(2,'0')} / ${nodes.length}</span><span>正文 ${n.page} 页</span></div><h3>${n.title}</h3><p class="question">${n.question}</p><div class="tabs"><button data-tab="transfer" class="${tab==='transfer'?'active':''}">上下游传递</button><button data-tab="method" class="${tab==='method'?'active':''}">数据与模型</button><button data-tab="output" class="${tab==='output'?'active':''}">输出与结果</button><button data-tab="source" class="${tab==='source'?'active':''}">原文证据</button></div><div id="tabBody">${body}</div><div class="source"><span>来源：项目报告 · 2025.07</span><a target="_blank" rel="noopener" href="assets/report.pdf#page=${n.pdf}">打开原文 ↗</a></div>`;document.querySelectorAll('[data-tab]').forEach(b=>b.onclick=()=>{tab=b.dataset.tab;renderDetail()});document.querySelectorAll('[data-jump]').forEach(b=>b.onclick=()=>{filter='all';updateFilters();select(b.dataset.jump)});const im=$('.evidence');if(im)im.onclick=()=>{$('#largeImage').src=im.src;$('#imageDialog').showModal()};}
function updateFilters(){document.querySelectorAll('[data-filter]').forEach(b=>b.classList.toggle('active',b.dataset.filter===filter));}
document.querySelectorAll('[data-filter]').forEach(b=>b.onclick=()=>{filter=b.dataset.filter;updateFilters();const allowed=nodes.filter(n=>filter==='all'||n.type===filter);if(filter!=='all'&&!allowed.some(n=>n.id===selected)){selected=allowed[0].id;tab='transfer';renderDetail()}renderMap()});
$('#search').oninput=renderMap;$('#guide').onclick=()=>{filter='all';$('#search').value='';updateFilters();select(nodes[(nodes.findIndex(n=>n.id===selected)+1)%nodes.length].id,true)};$('#closeImage').onclick=()=>$('#imageDialog').close();$('#imageDialog').onclick=e=>{if(e.target===$('#imageDialog'))$('#imageDialog').close()};
const years=[2035,2050,2070,2100],ssps=['SSP1-1.9','SSP2-4.5','SSP5-8.5'];const values=[[[.7,62.67,3.4],[1.21,108.45,5.88],[1.03,92.21,5.01]],[[2.03,188.7,10.24],[2.46,220.76,11.98],[2.22,199.43,10.83]],[[3.85,345.55,18.76],[4.01,360.22,19.55],[4.05,363.62,19.74]],[[6.42,582.86,31.64],[6.4,573.87,31.15],[7.76,696.69,37.82]]];
function scenario(){const y=+$('#year').value,s=+$('#ssp').value,v=values[y][s];$('#yearValue').textContent=years[y];$('#metrics').innerHTML=['水位增加','面积增加','水量增加'].map((l,i)=>`<div class="metric"><small>${l}</small><b>+${v[i].toFixed(2)}</b> <span>${['m','km²','km³'][i]}</span></div>`).join('');$('#bars').innerHTML='<div class="eyebrow">同一年 · 三种情景水位增量 / 固定0—8 m尺度</div>'+values[y].map((x,i)=>`<div class="bar-row ${s===i?'chosen':''}"><span>${ssps[i]}</span><div class="bar-track"><div class="bar-fill" style="width:${x[0]/8*100}%"></div></div><span>+${x[0].toFixed(2)} m</span></div>`).join('');$('#risk').textContent=['约1 m：部分位置湖面接近铁路；报告统计35个房屋点受淹。','约2 m：部分铁路、公路及房屋点受影响；报告统计115个房屋点受淹。','约4 m：约3 km铁路、约50 km公路面临淹没；报告统计305个房屋点受淹。','约6—8 m：暴露范围扩大；约6 m时586个房屋点，约8 m时981个。'][y];}
$('#year').oninput=scenario;$('#ssp').onchange=scenario;renderMatrix();renderMap();renderDetail();scenario();

